package com.finsight;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.security.crypto.password.PasswordEncoder;import com.finsight.domain.*;import com.finsight.repository.*;
@SpringBootApplication public class FinSightApplication {public static void main(String[]a){SpringApplication.run(FinSightApplication.class,a);}@Bean CommandLineRunner seed(UserRepository u,CustomerRepository c,PasswordEncoder p){return args->{if(u.count()==0){User x=new User();x.setEmail("demo@finsight.local");x.setPasswordHash(p.encode("FinSight123!"));u.save(x);Customer a=customer("Apex Manufacturing Pvt Ltd","Manufacturing",520000000d,92000000d,160000000d,74000000d,88);Customer b=customer("Nova Technologies Pvt Ltd","Technology",310000000d,51000000d,145000000d,38000000d,71);c.save(a);c.save(b);}};}static Customer customer(String n,String i,double r,double e,double d,double cash,int ph){Customer c=new Customer();c.setCompanyName(n);c.setIndustry(i);c.setAnnualRevenue(r);c.setEbitda(e);c.setTotalDebt(d);c.setCashBalance(cash);c.setPaymentHistoryScore(ph);return c;}}
